/bin/bash -lc "python3 - <<'PY'
from PIL import Image
import numpy as np
im=np.array(Image.open('first_frame.png'))
# masks
def runs(a,minlen=2):
 out=[];on=False
 for i,v in enumerate(np.r_[a,False]):
  if v and not on:s=i;on=True
  if on and not v:
   if i-s>=minlen:out.append((s,i-1,i-s))
   on=False
 return out
masks={
'red':(im[:,:,0]>130)&(im[:,:,0]>im[:,:,1]*1.3)&(im[:,:,0]>im[:,:,2]*1.25),
'vred':(im[:,:,0]>180)&(im[:,:,1]<110)&(im[:,:,2]<100),
'dark':im.mean(2)<60,
'neutralmid':(im.max(2)-im.min(2)<25)&(im.mean(2)>60)&(im.mean(2)<140),
}
for name,m in masks.items():
 print('\\n',name)
 for y in range(0,121,5): print(y,runs(m[y]))
# pixel samples and horizontal mean colors blocks in key ROI
for y in [0,10,20,30,40,50,60,65,70,75,80,85,90,95,100,105,110,120,130,140]:
 print('\\ny',y)
 for x in range(50,231,10):
  p=im[y,x];print(f'{x}:{p[0]:02x}{p[1]:02x}{p[2]:02x}',end=' ')
 print()
PY"
